import React, { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import MusicPlayer from './components/MusicPlayer';
import SubmitWork from './components/SubmitWork';
import Lottie from 'lottie-react';  // ✅ Correct import
import Home from './components/Home';
import { useAuth } from './components/AuthProvider';
import './global.css';

export default function App() {
  const [buddyAnimation, setBuddyAnimation] = useState(null);
  const [showHelp, setShowHelp] = useState(false);
  const { user, loginWithGoogle, logout } = useAuth();

  // ✅ Text-to-Speech Function (ENGLISH ONLY)
  const speak = (text) => {
    const synth = window.speechSynthesis;
    const utter = new SpeechSynthesisUtterance(text);
    utter.lang = "en-US";  // ✅ Force English
    utter.pitch = 1.5;
    utter.rate = 1.2;
    const voices = synth.getVoices();
    utter.voice = voices.find(v => v.lang === 'en-US' && v.name.includes("Google")) 
               || voices.find(v => v.lang === 'en-US') 
               || voices[0];
    synth.speak(utter);
  };

  // ✅ Load buddy.json animation
  useEffect(() => {
    fetch(`${process.env.PUBLIC_URL}/assets/buddy.json`)
      .then(res => res.json())
      .then(data => {
        console.log("Buddy loaded ✅", data);
        setBuddyAnimation(data);
      });
  }, []);

  // ✅ Speak greeting once when voices ready
  useEffect(() => {
    const greet = () => speak("Hi! I'm Buddy! Want some help?");
    if (window.speechSynthesis.getVoices().length > 0) {
      greet();
    } else {
      window.speechSynthesis.onvoiceschanged = () => {
        greet();
        window.speechSynthesis.onvoiceschanged = null;
      };
    }
    return () => {
      window.speechSynthesis.onvoiceschanged = null;
    };
  }, []);

  const toggleHelp = () => setShowHelp(!showHelp);

  return (
    <Router>
      <div 
        style={{ 
          backgroundImage: "url('/assets/doodle-bg.png')", 
          backgroundRepeat: "repeat", 
          backgroundSize: "contain", 
          minHeight: "100vh" 
        }}
      >
        <div className="navbar">
          WritingBuddy 🖋️
          {user ? (
            <button onClick={logout} className="login-btn">Logout</button>
          ) : (
            <button onClick={loginWithGoogle} className="login-btn">Login with Google</button>
          )}
        </div>

        <MusicPlayer />

        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/submit" element={<SubmitWork />} />
        </Routes>

        {/* 🧸 Buddy Mascot  */}
        {buddyAnimation && (
  <div className="mascot" onClick={toggleHelp} title="Click me for help!">
    <Lottie 
      animationData={buddyAnimation} 
      loop={true} 
      autoplay={true} 
      style={{ height: 200, width: 200 }} 
    />
  </div>
)}
        {/* 💬 Help Pop-Up with Voice */}
        {showHelp && (
          <div className="help-popup">
            <h4>Hi there! Need help? 😊</h4>
            <ul>
              <li onClick={() => speak("Click the essays button to view samples!")}>Where are essays?</li>
              <li onClick={() => speak("Click the letters button to see example letters!")}>How to write a letter?</li>
              <li onClick={() => speak("Sure! Click submit to send us your story!")}>Can I submit my story?</li>
            </ul>
          </div>
        )}
      </div>
    </Router>
  );
}