import React from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css'; // Optional: if you want additional styles

export default function Home() {
  const navigate = useNavigate();

  return (
    <div className="home-container">
      <h1 className="welcome-title">Welcome to <span className="highlight">WritingBuddy!</span> 🧸</h1>
      <p className="intro-text">
        We help school students with model essays, letters, short poems, and moral stories —
        all in a fun and friendly way! ✨📚
      </p>

      <div className="content-buttons">
        <button className="pastel-btn">📄 Essays</button>
        <button className="pastel-btn">✉️ Letters</button>
        <button className="pastel-btn">📝 Short Poems</button>
        <button className="pastel-btn">📖 Moral Stories</button>
      </div>

      <h3 className="submit-title">Submit Your Own Work ✍️</h3>
      <button className="submit-btn" onClick={() => navigate('/submit')}>
        Click to Submit
      </button>
    </div>
  );
}